const canvas=document.querySelector('#siteCanvas');let selected=document.querySelector('.selected');let zoom=90;let history=[];let historyIndex=-1;
const templates={hero:'<section class="inserted section-block" data-name="Hero" tabindex="0"><div class="selection-tag">Hero</div><span class="overline">YOUR NEXT BIG IDEA</span><h3 contenteditable="true">A headline that gets attention.</h3><p contenteditable="true">Add a short description that makes the value clear.</p></section>',features:'<section class="inserted section-block" data-name="Feature grid" tabindex="0"><div class="selection-tag">Feature grid</div><span class="overline">WHY CHOOSE US</span><h3 contenteditable="true">Everything you need to grow.</h3><p>Fast setup · Reliable infrastructure · Human support</p></section>',pricing:'<section class="inserted section-block" data-name="Pricing plans" tabindex="0"><div class="selection-tag">Pricing plans</div><span class="overline">PLANS</span><h3 contenteditable="true">Simple pricing, no surprises.</h3><p>Starter $4.99 · Community $9.99 · Pro $19.99 · Ultimate $39.99</p></section>',games:'<section class="inserted section-block" data-name="Game selector" tabindex="0"><div class="selection-tag">Game selector</div><span class="overline">GAME SERVERS</span><h3 contenteditable="true">Find your game.</h3><p>Minecraft · Palworld · Terraria · Hytale · Factorio</p></section>',quote:'<section class="inserted section-block" data-name="Custom quote" tabindex="0"><div class="selection-tag">Custom quote</div><span class="overline">CUSTOM INFRASTRUCTURE</span><h3 contenteditable="true">Need something bigger?</h3><p>Build a custom server and get an instant estimated monthly price.</p></section>',footer:'<footer class="inserted section-block" data-name="Footer" tabindex="0"><div class="selection-tag">Footer</div><h3 contenteditable="true">UNDERLINE</h3><p>Game hosting built for worlds that grow.</p></footer>'};
function snapshot(){const html=canvas.innerHTML;if(history[historyIndex]===html)return;history=history.slice(0,historyIndex+1);history.push(html);historyIndex=history.length-1;setSaved(false)}
function restore(i){if(!history[i])return;historyIndex=i;canvas.innerHTML=history[i];wireSections();select(canvas.querySelector('.section-block'));setSaved(true)}
function setSaved(done){const el=document.querySelector('#saveState');el.innerHTML=`<i></i> ${done?'Saved':'Saving…'}`;clearTimeout(window.saveTimer);window.saveTimer=setTimeout(()=>{localStorage.setItem('webkiln-page',canvas.innerHTML);el.innerHTML='<i></i> Saved'},700)}
function select(el){if(!el)return;document.querySelectorAll('.section-block').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selected=el;const name=el.dataset.name||'Section';document.querySelector('#inspectorTitle').textContent=name;document.querySelector('#selectionLabel').textContent=name;const style=getComputedStyle(el);document.querySelector('#bgColor').value=toHex(style.backgroundColor)||'#0b0d0f';document.querySelector('#textColor').value=toHex(style.color)||'#f7f7f5'}
function wireSections(){document.querySelectorAll('.section-block').forEach(el=>{el.onclick=e=>{if(e.target.closest('button,a,input'))return;e.stopPropagation();select(el)}})}
function toHex(rgb){const m=rgb.match(/\d+/g);if(!m||m.length<3)return null;return '#'+m.slice(0,3).map(x=>(+x).toString(16).padStart(2,'0')).join('')}
function addBlock(type){if(!templates[type])return;document.querySelector('#dropZone').insertAdjacentHTML('beforebegin',templates[type]);wireSections();select(document.querySelector('#dropZone').previousElementSibling);snapshot()}
document.querySelectorAll('.block-card').forEach(card=>{card.addEventListener('click',()=>addBlock(card.dataset.type));card.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',card.dataset.type))});
const dz=document.querySelector('#dropZone');['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag-active')}));dz.addEventListener('dragleave',()=>dz.classList.remove('drag-active'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('drag-active');addBlock(e.dataTransfer.getData('text/plain'))});
document.querySelectorAll('.rail-tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.rail-tab,.panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector(`#${btn.dataset.panel}Panel`).classList.add('active')});
document.querySelectorAll('.chip').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.block-card').forEach(card=>card.hidden=btn.dataset.filter!=='all'&&card.dataset.category!==btn.dataset.filter)});
document.querySelector('#blockSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.block-card').forEach(x=>x.hidden=!x.innerText.toLowerCase().includes(q))};
document.querySelectorAll('.device').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.device').forEach(x=>x.classList.remove('active'));btn.classList.add('active');canvas.className=`site-canvas ${btn.dataset.width}`});
document.querySelector('#spacingRange').oninput=e=>{if(selected){selected.style.paddingTop=e.target.value+'px';selected.style.paddingBottom=e.target.value+'px';document.querySelector('#spacingValue').textContent=e.target.value+' px'}};
document.querySelector('#spacingRange').onchange=snapshot;document.querySelector('#bgColor').oninput=e=>{if(selected){selected.style.background=e.target.value;document.querySelector('#bgValue').textContent=e.target.value.toUpperCase()}};document.querySelector('#bgColor').onchange=snapshot;document.querySelector('#textColor').oninput=e=>{if(selected){selected.style.color=e.target.value;document.querySelector('#textValue').textContent=e.target.value.toUpperCase()}};document.querySelector('#textColor').onchange=snapshot;
document.querySelector('#themeColor').oninput=e=>document.documentElement.style.setProperty('--gold',e.target.value);document.querySelector('#radiusSelect').onchange=e=>document.documentElement.style.setProperty('--radius',e.target.value+'px');
document.querySelector('#deleteBtn').onclick=()=>{if(selected&&document.querySelectorAll('.section-block').length>1){const next=selected.nextElementSibling||selected.previousElementSibling;selected.remove();select(next?.classList.contains('section-block')?next:document.querySelector('.section-block'));snapshot()}};
document.querySelector('.outline-btn').onclick=()=>{if(selected){selected.insertAdjacentHTML('afterend',selected.outerHTML);wireSections();select(selected.nextElementSibling);snapshot()}};
document.querySelector('#undoBtn').onclick=()=>restore(historyIndex-1);document.querySelector('#redoBtn').onclick=()=>restore(historyIndex+1);
document.querySelector('#zoomOut').onclick=()=>{zoom=Math.max(50,zoom-10);canvas.style.transform=`scale(${zoom/100})`;document.querySelector('#zoomValue').textContent=zoom+'%'};document.querySelector('#zoomIn').onclick=()=>{zoom=Math.min(120,zoom+10);canvas.style.transform=`scale(${zoom/100})`;document.querySelector('#zoomValue').textContent=zoom+'%'};
document.querySelector('#previewBtn').onclick=()=>{document.querySelector('.left-rail').classList.toggle('preview-hidden');document.querySelector('.inspector').classList.toggle('preview-hidden');document.querySelector('.editor-shell').classList.toggle('preview-mode')};
document.querySelector('#publishBtn').onclick=()=>{localStorage.setItem('webkiln-page',canvas.innerHTML);const t=document.querySelector('#toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)};
canvas.addEventListener('input',()=>setSaved(false));canvas.addEventListener('focusout',snapshot);wireSections();snapshot();
